import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Count totals
    opp_c = 0
    opp_d = 0
    my_c = 0
    my_d = 0
    cc = 0
    dd = 0
    cd = 0
    dc = 0
    for (me, op) in history:
        if op == 'C':
            opp_c += 1
        else:
            opp_d += 1
        if me == 'C':
            my_c += 1
        else:
            my_d += 1
        if me == 'C' and op == 'C':
            cc += 1
        elif me == 'D' and op == 'D':
            dd += 1
        elif me == 'C' and op == 'D':
            cd += 1
        else:
            dc += 1

    opp_rate = opp_c / n

    # Early game: be nice, reciprocate opening defection gently
    if n < 3:
        return 'C'

    # Endgame: squeeze
    rounds_left = 100 - n

    # Against near-pure cooperator, exploit heavily near end
    if opp_rate > 0.92 and n >= 12:
        if rounds_left <= 8:
            return 'D'
        # mid-game exploit probabilistically but keep them cooperating
        if rng.random() < 0.25:
            return 'D'
        return 'C'

    # Against near-pure defector, defect (only rare probe)
    if opp_rate < 0.1 and n >= 12:
        if rounds_left > 5 and rng.random() < 0.04:
            return 'C'
        return 'D'

    # Determine last few opponent moves
    look = min(6, n)
    recent_opp_d = 0
    recent_opp_c = 0
    for i in range(n - look, n):
        if history[i][1] == 'D':
            recent_opp_d += 1
        else:
            recent_opp_c += 1

    last_op = history[-1][1]
    last_me = history[-1][0]

    # Under attack: short punishment then forgiveness / repair
    if last_op == 'D':
        # Count consecutive opponent defections at the tail
        run_d = 0
        i = n - 1
        while i >= 0 and history[i][1] == 'D':
            run_d += 1
            i -= 1

        if run_d == 1:
            # Isolated defection: often forgive to preserve cooperation
            # unless opponent is generally uncooperative
            if opp_rate > 0.6:
                # Mostly forgiving
                if rng.random() < 0.7:
                    return 'C'
                return 'D'
            else:
                # Less forgiving if partner generally defecting
                if rng.random() < 0.35:
                    return 'C'
                return 'D'

        # Short punishment window, then try to repair
        if run_d == 2:
            # alternate/retaliate: tends to produce successful repair
            return 'D'
        if run_d == 3:
            # try conciliatory C to break lock-in
            if opp_rate > 0.4 and rng.random() < 0.55:
                return 'C'
            return 'D'
        # long run
        if opp_rate > 0.4:
            # opponent typically cooperates, so unprompted long defection = exploit
            return 'D'
        # generally defective partner: probe occasionally
        if rng.random() < 0.06:
            return 'C'
        return 'D'

    # Opponent cooperated
    # If our last action was D and they still cooperated, they're forgiving: exploit gently
    if last_me == 'D':
        if opp_rate > 0.85 and rounds_left > 12 and rng.random() < 0.45:
            return 'D'
        return 'C'

    # Both cooperated (or we just cooperated)
    if recent_opp_d == 0:
        # Perfect recent cooperation: stay cooperative, small mid-game probe vs naive
        if n > 25 and rounds_left > 12 and opp_rate > 0.9 and rng.random() < 0.06:
            return 'D'
        return 'C'

    # Some recent defects but last was C: gentle mix based on rate
    if opp_rate > 0.7:
        if rng.random() < 0.85:
            return 'C'
        return 'D'
    if opp_rate > 0.4:
        if rng.random() < 0.65:
            return 'C'
        return 'D'
    if rng.random() < 0.3:
        return 'C'
    return 'D'
